void LuaScriptEngine::LoadScripts(const char *filename)
{
	File *file = TheFileSystem->openFile(filename, 0x41, 0);
	if (!file)
		return;
	int size = file->size();
	char *buff = new char[size + 10];
	file->read(buff, size);
	file->close();
	ExecuteChunk(buff, size, AsciiString(filename));
	delete[] buff;
}

